/** Preset with overrides (e.g. a sunset spot with its own sun azimuth and water colours). */
export function envPreset(time: EnvDef['timeOfDay'], overrides: Partial<EnvDef> = {}): EnvDef {
  return { ...ENV_PRESETS[time], ...overrides, timeOfDay: time };
}
